package com.autoops.credential.entity; import jakarta.persistence.*;import java.time.Instant; @Entity @Table(name="credentials") public class Credential{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String name;@Column(nullable=false)private String username;@Column(name="encrypted_password",nullable=false,columnDefinition="text")private String encryptedPassword;@Column(name="encryption_iv",nullable=false)private String encryptionIv;@Column(name="auth_type",nullable=false)private String authType="PASSWORD";@Column(name="created_by",nullable=false)private Long createdBy;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getEncryptedPassword(){return encryptedPassword;}public void setEncryptedPassword(String v){encryptedPassword=v;}public String getEncryptionIv(){return encryptionIv;}public void setEncryptionIv(String v){encryptionIv=v;}public Long getCreatedBy(){return createdBy;}public void setCreatedBy(Long v){createdBy=v;}}
